ff-utility.scss';\n\n$sidenav_width: 250px;\n$transition_time: .15s;\n\n/*\n    Layout - Box\n        used in login/setup/signup screens\n*/\n\n$nav_height: 60px;\n\n.ff-layout--box {\n    font-family: 'Heebo', system-ui, sans-serif;\n    background-color: $ff-white;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100%;\n    min-height: inherit;\n    background-image: url(\"./images/ff-bg-flow.jpg\");\n    background-size: cover;\n    background-repeat: no-repeat;\n    background-position: center center;\n    color: $ff-grey-700;\n    .ff-error-inline {\n        font-size: 0.875rem;;\n        display: block;\n        margin-top: 0.25rem;\n        color: $ff-red-200;\n    }\n\n    &.ff--center-box {\n        flex-direction: column;\n        min-height: fit-content;\n        overflow: auto;\n\n        .ff-layout--box--wrapper {\n            display: flex;\n            width: 100%;\n            max-height: fit-content;\n            height: fit-content;\n\n            .ff-layout--box--left,\n            .ff-layout--box--right {\n                width: 100%;\n            }\n        }\n    }\n}\n\n.ff-layout--box--wrapper {\n    width: calc(100% - 48px);\n    height: 60%;\n    display: grid;\n}\n.ff-layout--box--left {\n    .ff-logo {\n        max-width: 150px;\n        margin-bottom: 16px;\n    }\n}\n.ff-layout--box--right {\n    .ff-logo {\n        max-width: 200px;\n        margin: auto;\n        margin-bottom: 48px;\n    }\n}\n\n.ff-layout--box--left,\n.ff-layout--box--right {\n    height: 100%;\n    justify-content: center;\n    align-items: center;\n}\n\n.ff-layout--box--left {\n    h1 {\n        max-width: 420px;\n    }\n    h3 {\n        font-size: 1.25rem;\n    }\n    p {\n        font-weight: 300;\n        line-height: 1.5rem;\n    }\n}\n\n.ff-layout--box--content {\n    width: 100%;\n}\n\n.ff-layout--box--right .ff-layout--box--content {\n    min-height: 400px;\n    padding: 64px 24px;\n    @apply rounded-xl;\n    color: $ff-grey-700;\n    h2 {\n        margin-top: -12px;\n        margin-bottom: 24px;\n    }\n    h5 {\n        font-weight: bold;\n        margin-bottom: 0.75rem;\n    }\n    label {\n        display: block;\n        color: $ff-grey-700;\n        margin-bottom: 4px;\n    }\n    .ff-radio-btn label {\n        font-weight: normal;\n    }\n    p {\n        margin-bottom: 1rem;\n    }\n    a {\n        color: $ff-blue-600;\n    }\n    .ff-input:not(.ff-input--error) {\n        border-color: $ff-grey-300;\n    }\n    .ff-input {\n        border-width: 2px;\n        &:focus-within {\n            border-color: $ff-indigo-600;\n        }\n    }\n    .ff-radio-btn {\n        .checkbox {\n          border: 1px solid $ff-grey-400;\n        }\n    }\n\n    .ff-error-inline {\n        margin-bottom: 12px;\n    }\n\n    .ff-actions {\n        margin-top: 18px;\n    }\n    .ff-btn {\n        text-transform: uppercase;\n        width: 100%;\n        margin-bottom: 6px;\n    }\n    .ff-btn.ff-btn--primary {\n        background-color: $ff-indigo-600;\n        color: white;\n        &:hover {\n            background-color: $ff-indigo-700;\n        }\n        &:disabled {\n            background-color: $ff-grey-300;\n            color: $ff-grey-400;\n        }\n    }\n    .ff-btn.ff-btn--tertiary {\n        color: $ff-indigo-500;\n        font-weight: normal;\n        border: 1px solid transparent;\n        &:hover {\n            background-color: transparent;\n            border-color: $ff-indigo-600;\n        }\n    }\n}\n\n/*\n    Layout - Platform / Plain\n        used in all other pages\n*/\n\n.ff-layout--platform,\n.ff-layout--plain {\n    min-height: inherit;\n    flex: 1;\n    display: flex;\n    flex-direction: column;\n}\n\n.ff-layout--platform--wrapper{\n    padding-top: $nav_height;\n    position: absolute;\n    width: 100%;\n    height: 100%;\n    overflow: hidden;\n    display: flex;\n    flex-direction: row;\n\n    .ff-view {\n        display: flex;\n        flex-direction: column;\n        position: relative;\n        overflow-y: auto;\n        overflow-x: hidden;\n        width: 100%;\n        height: 100%;\n        transition: ease-in-out margin-left .3s;\n    }\n    main {\n        background-color: $ff-grey-50;\n    }\n    .ff-page-header {\n        background-color: $ff-white;\n        border-color: $ff-color--border;\n    }\n}\n\n.ff-layout--plain--wrapper {\n    height: 100%;\n    display: flex;\n    flex-direction: column;\n    flex: 1;\n\n    main {\n        background-color: $ff-grey-50;\n        flex: 1;\n    }\n}\n\n.ff-notifications {\n    position: absolute;\n    right: 12px;\n    top: $nav_height + 12px;\n    z-index: 130;\n    min-width: 350px;\n}\n\n.ff-notification-toast {\n    min-height: $nav_height;\n    margin-bottom: $ff-unit-md;\n}\n\n.notifications-list-move,\n.notifications-list-enter-active,\n.notifications-list-leave-active {\n    transition: all 0.3s ease;\n}\n\n.notifications-list-enter-from,\n.notifications-list-leave-to {\n    opacity: 0;\n    transform: translateX(200px);\n}\n\n.notifications-list-leave-active {\n    position: absolute;\n}\n\n.ff-team-selection {\n    position: relative;\n    display: flex;\n    justify-content: space-between;\n    min-width: $sidenav_width;\n    .ff-dropdown-options {\n        position: absolute;\n        min-width: $sidenav_width;\n        display: block;\n        z-index: 10;\n        border-bottom: 0;\n        max-height: initial;\n        &.active {\n            display: block;\n        }\n        .ff-dropdown-option {\n            padding: 0;\n            border-bottom: none;\n        }\n    }\n}\n.ff-team-selection-name {\n    margin-left: 10px;\n    display: flex;\n    flex-direction: column;\n    justify-content: center;\n    align-items: flex-start;\n    label {\n        font-size: 0.7rem;\n        line-height: 0.7rem;\n        color: $ff-grey-500;\n        margin-left: 0;\n    }\n    h5 {\n        color: $ff-grey-800;\n        white-space: nowrap;\n    }\n}\n.ff-team-selection > div {\n    flex-grow: 1;\n    display: flex;\n    align-items: center;\n    cursor: pointer;\n    &:hover {\n        label, h5 {\n            color: $ff-teal-200;\n        }\n    }\n}\n.ff-banner {\n    background-color: $ff-grey-800;\n    color: $ff-grey-300;\n    padding: 8px;\n    text-align: center;\n    border-bottom: 2px solid $ff-red-500;\n\n    &.ff-banner-info {\n        background-color: $ff-blue-100;\n        color: $ff-grey-700;\n        text-align: left;\n        border-bottom: none;\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        padding-left: 16px;\n        padding-right: 16px;\n    }\n\n    &.ff-banner-warning {\n        background-color: $ff-red-700;\n        color: $ff-grey-50;\n        text-align: left;\n        border-bottom: 2px solid $ff-red-800;\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        padding-left: 16px;\n        padding-right: 16px;\n    }\n}\n.ff-header {\n    z-index: 110;\n    background-color: $ff-white;\n    height: $nav_height;\n    border-bottom: 1px solid $ff-color--border;\n    display: flex;\n    align-items: center;\n    justify-content: space-between;\n    position: fixed;\n    width: 100%; \n    img.ff-logo {\n        padding-top: 18px;\n        padding-bottom: 18px;\n        height: $nav_height;\n        &:hover {\n            cursor: pointer;\n        }\n    }\n    .ff-header--mobile-toggle {\n        padding: 16px;\n        svg {\n            fill: $ff-grey-800;\n            min-width: 24px;\n        }\n        &.active {\n            cursor: pointer;\n            background-color: $ff-grey-700;\n        }\n    }\n    .ff-header--mobile-usertoggle {\n        padding: 16px;\n        img {\n            padding: 0;\n            min-width: 24px;\n        }\n        &.active {\n            cursor: pointer;\n            background-color: $ff-grey-100;\n        }\n    }\n    .ff-navigation {\n        position: absolute;\n        display: flex;\n        flex-direction: column;\n        top: 100%;\n        //margin-top: 2px;\n        img {\n            padding: 0;\n            margin-right: 9px;\n        }\n        .ff-user {\n            display: flex;\n            align-items: center;\n            margin-left: -2px;\n            position: relative;\n            transition: ease-in-out .1s;\n            object-fit: contain;\n            will-change: transform;\n            .ff-notification-pill {\n                font-size: 0.65rem;\n                padding: 0px 6px;\n                background-color: $ff-red-600;\n                border: 1px solid $ff-grey-800;\n                position: absolute;\n                bottom: -9px;\n                line-height: 0.85rem;\n                right: 0;\n            }\n            &:hover {\n                transform: scale(1.25) translateZ(0); /* Using slight adjustments to whole values */\n                backface-visibility: hidden;\n                perspective: 1000px;\n                stroke-width: 1.5px;\n                shape-rendering: geometricPrecision;\n                text-rendering: geometricPrecision;\n            }\n        }\n    }\n    .ff-border-left {\n        border-width: 0 0 0 1px;\n        border-color: $ff-grey-500;\n    }\n    .ff-navigation-right {\n        height: 100%;\n        ul {\n            background: $ff-white;\n            border: 1px solid $ff-color--border;\n            \n            .ff-nav-item {\n                transition: ease-in-out .3s;\n                &:hover {\n                    background: $ff-grey-100;\n                    label, svg {\n                        color: $ff-indigo-700;\n                        fill: $ff-indigo-700;\n                    }\n                }\n            }\n        }\n    }\n    .ff-desktop-navigation-right {\n        & > * {\n            position: relative;\n            &:after {\n                position: absolute;\n                content: '';\n                width: 1px;\n                height: 15px;\n                background: $ff-color--border;\n                top: 40%;\n            }\n        }\n    }\n    .ff-mobile-navigation-right {\n        img,\n        button {\n            cursor: pointer;\n        }\n    }\n    .ff-dropdown {\n        color: white;\n        min-width: $sidenav_width;\n        position: relative;\n        top: 0;\n        margin-top: 0;\n        .ff-dropdown-selected {\n            background: none;\n            padding: 16px 16px 16px 24px;\n            display: flex;\n            flex: 1;\n            justify-content: space-between;\n            align-items: center;\n            border: none;\n            border-radius: 0;\n        }\n        .ff-dropdown-options {\n            width: 100%;\n            border-color: $ff-color--border;\n            border-right: 0;\n            \n            .ff-dropdown-option {\n                &:hover {\n                    label, svg {\n                        color: $ff-indigo-700;\n                        fill: $ff-indigo-700;\n                    }\n                }   \n            }\n        }\n    }\n    .ff-user-options {\n        width: auto;\n        min-width: $nav_height;\n\n        &.ff-navigation {\n            left: auto;\n        }\n        .ff-dropdown-options {\n            width: $sidenav_width;\n        }\n    }\n}\n\n.ff-user-options {\n    .ff-dropdown-options {\n        max-height: initial;\n        .ff-dropdown-option {\n            border-bottom: none;\n            \n            &.danger {\n                label, svg {\n                    color: $ff-red-700;\n                    fill: $ff-red-700;\n                }\n            }\n        }\n    }\n}\n\n\n.ff-navigation,\n.ff-team-selection ul {\n    .ff-nav-item {\n        &:hover {\n            cursor: pointer;\n        }\n    }\n}\n\n.ff-navigation .ff-nav-item {\n    border-bottom: 1px solid $ff-grey-600;\n    padding: 16px 16px 16px 24px;\n    display: grid;\n    grid-template-columns: 20px 1fr;\n    svg {\n        fill: $ff-grey-500;\n        width: 20px;\n    }\n    svg.hollow {\n        fill: none;\n        stroke: $ff-white;\n    }\n    label {\n        margin-left: 12px;\n        color: $ff-grey-800;\n        white-space: nowrap;\n        pointer-events: none;\n    }\n}\n\n.ff-team-selection ul .ff-nav-item {\n    border-bottom: 1px solid $ff-grey-600;\n    padding: 16px 16px 16px 22px;\n    display: grid;\n    align-items: center;\n    grid-template-columns: 24px 1fr;\n    height: $nav_height;\n    svg {\n        fill: $ff-white;\n        width: 20px;\n    }\n    label {\n        margin-left: 12px;\n        color: $ff-white;\n        white-space: nowrap;\n        pointer-events: none;\n    }\n}\n\n.ff-navigation {\n    position: fixed;\n    left: -$sidenav_width;\n    z-index: 10;\n    transition: 0.3s left, 0.3s right;\n    -webkit-transition: 0.3s left, 0.3s right;\n    width: $sidenav_width;\n    // handle router-link active styling for primary options\n    .ff-side-navigation--primary {\n        width: 100%;\n        transition: $transition_time width;\n        -webkit-transition: $transition_time width;\n        .router-link-active {\n            li {\n                label {\n                    color: $ff-teal-300;\n                }\n                svg {\n                    fill: $ff-teal-300;\n                    &.hollow {\n                        fill: none;\n                        stroke: $ff-teal-300;\n                    }\n                }\n            }\n        }\n    }\n    // nested menu options, including router-link highlighting\n    .ff-side-navigation--nested {\n        width: 0;\n        overflow: hidden;\n        .ff-nested-title {\n            color: $ff-teal-300;\n            font-weight: bold;\n            font-size: 1.1rem;\n            padding: 12px 16px;\n            white-space: nowrap;\n            overflow: hidden;\n            text-overflow: ellipsis;\n        }\n        .ff-nav-item {\n            padding: 12px 16px;\n        }\n        .router-link-active {\n            li {\n                background-color: $ff-grey-600;\n            }\n            label {\n                color: $ff-teal-300;\n            }\n            svg {\n                fill: $ff-teal-300;\n                &.hollow {\n                    fill: none;\n                    stroke: $ff-teal-300;\n                }\n            }\n        }\n    }\n    // navigation-right = the admin/user settings\n    &.ff-navigation-right {\n        left: initial;\n        right: -$sidenav_width;\n        .ff-nav-item {\n            &.danger {\n                label, svg {\n                    color: $ff-red-700;\n                    fill: $ff-red-700;\n                }   \n            }\n            &.create {\n                background: $ff-grey-100;\n                border-bottom: none;\n            }\n        }\n\n        &.without-divider {\n            .ff-nav-item:last-child {\n                border-top: unset;\n            }\n        }\n    }\n    &.open {\n        left: 0;\n    }\n    &.closed {\n        left: -$sidenav_width;\n    }\n    &.ff-navigation-right.open {\n        left: initial;\n        right: 0;\n    }\n    .ff-navigation-divider {\n        background-color: $ff-grey-900;\n        color: white;\n        padding: 6px 12px;\n        height: 32px;\n        display: block;\n        font-size: 0.85rem;\n        border-bottom: 1px solid $ff-grey-600;\n        text-overflow: ellipsis;\n        white-space: nowrap;\n        overflow: hidden;\n    }\n    .ff-dropdown-options .ff-dropdown-option {\n        padding: 0;\n    }\n    .ff-nav-item {\n        display: flex;\n        justify-content: space-between;\n        border-bottom: 1px solid $ff-color--border;\n    }\n    .disabled {\n        pointer-events: none;\n        opacity: 0.5;\n    }\n    .ff-notification-pill {\n        padding: 2px 12px;\n        background-color: $ff-red-600;\n        border: 1px solid $ff-red-700;\n    }\n    .ff-side-navigation--options-back {\n        li {\n            border-top: 1px solid $ff-grey-600;\n        }\n    }\n}\n\n/* MOBILE LAYOUT */\n@media screen and (min-width: $ff-screen-lg) {\n    /* Box */\n    .ff-layout--box--wrapper {\n        width: 85%;\n    }\n    .ff-navigation {\n        left: 0;\n        position: relative;\n    }\n    .ff-header {\n        .ff-header--mobile-toggle {\n            display: none;\n        }\n        .ff-header--mobile-usertoggle,\n        .ff-header--mobile-notificationstoggle {\n            display: none;\n        }\n        img.ff-logo {\n            padding: 18px;\n        }\n    }\n}\n\n#ff-app {\n    #left-drawer {\n        min-width: $sidenav_width;\n        position: relative;\n        transition: ease-in-out left .3s;\n        height: 100%;\n        z-index: 100;\n        left: 0;\n        background: $ff-color--context-menu;\n        border-right: 1px solid $ff-color--border;\n        overflow: auto;\n\n        .ff-main-navigation {\n            .ff-menu-groups {\n                padding-top: 10px;\n\n                .ff-menu-group {\n                    padding: 5px;\n\n                    .ff-group-title {\n                        margin: 10px 0 15px;\n                        padding: 0 10px;\n                        text-transform: uppercase;\n                        color: $ff-color--disabled;\n                        font-size: 11px;\n                    }\n\n                    .ff-menu-entries {\n\n                        .ff-menu-entry {\n                            margin: 0 10px 5px 10px;\n\n                            &:last-of-type {\n                                margin-bottom: 0;\n                            }\n\n                            .ff-nav-item {\n                                padding: 5px 10px;\n                                border-radius: 5px;\n\n                                & > div {\n                                    gap: 5px;\n      